 void RebuildBounds(){laneBounds.Clear();foreach(var l in D.lanes){if(l.points==null||l.points.Length==0)continue;var b=new Bounds(l.points[0].V(),Vector3.zero);foreach(var p in l.points)b.Encapsulate(p.V());b.Expand(Mathf.Max(2,l.width));laneBounds[l.id]=b;}}
