  if(pending!="") {EditorGUILayout.HelpBox(pending=="connect"?"연결할 다음 차로를 클릭하세요.":pending=="bind"?"연결할 차로를 클릭하세요.":pending=="target"?"연결할 노면 시설을 클릭하세요.":"Scene 지면을 클릭해 배치하세요.",MessageType.Info);Button("작업 취소",()=>pending="");}
