 void DrawSignals(){var rules=session.Baseline.junctionRules??new HybridJunctionRule[0];if(rules.Length>0){int selected=Mathf.Max(0,Array.FindIndex(rules,r=>r.id==junction));selected=EditorGUILayout.Popup("편집 교차로",selected,rules.Select(r=>r.id+" ("+r.x.ToString("0")+", "+r.z.ToString("0")+")").ToArray());junction=rules[selected].id;}junction=EditorGUILayout.TextField("교차로 ID",junction);if(Facility!=null&&GUILayout.Button("선택 시설 교차로 사용"))junction=Facility.junctionId;Button("교차로 원본 복원",()=>{if(EditorUtility.DisplayDialog("교차로 복원",junction+"의 차로·시설·신호를 기준 지도 상태로 복원합니다.","복원","취소"))Edit("교차로 복원",d=>RoadMapAuthoringOperations.RestoreJunction(d,RoadMapDocument.Create(session.Baseline),junction));});Button("신호 프로그램 재생성",()=>{if(EditorUtility.DisplayDialog("신호 재생성","현재 프로그램을 보수적 기본 프로그램으로 바꿉니다.","재생성","취소")){CreateProgram();}});var p=D.signals.FirstOrDefault(s=>s.junctionId==junction);if(p==null){Button("보수적 기본 신호 프로그램 생성",()=>CreateProgram());return;}EditorGUILayout.LabelField("주기 "+p.Cycle.ToString("0.0")+"초",EditorStyles.boldLabel);
  for(int i=0;i<p.stages.Length;i++){int n=i;var s=p.stages[i];EditorGUI.BeginChangeCheck();string name=EditorGUILayout.TextField("단계 "+(i+1),s.name);float green=EditorGUILayout.FloatField("녹색 초",s.green),yellow=EditorGUILayout.FloatField("황색 초",s.yellow),clear=EditorGUILayout.FloatField("전적색 초",s.clearance);if(EditorGUI.EndChangeCheck())Edit("신호 시간",d=>{var x=d.signals.First(a=>a.junctionId==junction).stages[n];x.name=name;x.green=Mathf.Max(1,green);x.yellow=Mathf.Max(0,yellow);x.clearance=Mathf.Max(1,clear);});foreach(var g in p.groups){bool old=s.groups.Contains(g.id),v=EditorGUILayout.Toggle(g.name,old);if(v!=old)Edit("단계 그룹",d=>{var x=d.signals.First(a=>a.junctionId==junction).stages[n];x.groups=v?x.groups.Concat(new[]{g.id}).ToArray():x.groups.Where(a=>a!=g.id).ToArray();});}Button("단계 삭제 "+(i+1),()=>Edit("단계 삭제",d=>{var x=d.signals.First(a=>a.junctionId==junction);x.stages=x.stages.Where((a,k)=>k!=n).ToArray();}));}
  Button("단계 추가",()=>Edit("단계 추가",d=>{var x=d.signals.First(a=>a.junctionId==junction);x.stages=x.stages.Concat(new[]{new RoadMapStage()}).ToArray();}));
  foreach(var g in p.groups){EditorGUILayout.LabelField(g.name,EditorStyles.boldLabel);Button(g.pedestrian?"Scene 횡단보도를 그룹에 연결":"Scene 차로를 그룹에 추가",()=>{selectedGroup=g.id;pending=g.pedestrian?"groupWalk":"groupLane";});EditorGUI.BeginChangeCheck();string name=EditorGUILayout.TextField("그룹 이름",g.name);bool pedestrian=EditorGUILayout.Toggle("보행",g.pedestrian);int axis=EditorGUILayout.IntSlider("축",g.axis,0,1),sign=EditorGUILayout.IntPopup("방향",g.sign,new[]{"+","−"},new[]{1,-1}),gt=EditorGUILayout.IntSlider("회전 (-2 유턴 / -1 좌 / 0 직 / 1 우)",g.turn,-2,1);string lanes=EditorGUILayout.TextField("대상 차로 (쉼표)",string.Join(",",g.laneIds)),crosswalk=EditorGUILayout.TextField("횡단보도 ID",g.crosswalkId);if(EditorGUI.EndChangeCheck())Edit("신호 그룹",d=>{var x=d.signals.First(a=>a.junctionId==junction).groups.First(a=>a.id==g.id);x.name=name;x.pedestrian=pedestrian;x.axis=axis;x.sign=sign;x.turn=gt;x.crosswalkId=crosswalk;x.laneIds=lanes.Split(',').Select(a=>a.Trim()).Where(a=>a!="").ToArray();});Button("그룹 삭제 "+g.name,()=>Edit("그룹 삭제",d=>{var x=d.signals.First(a=>a.junctionId==junction);x.groups=x.groups.Where(a=>a.id!=g.id).ToArray();foreach(var s in x.stages)s.groups=s.groups.Where(a=>a!=g.id).ToArray();}));}
