 void AddGroup(bool pedestrian){var rule=(session.Baseline.junctionRules??new HybridJunctionRule[0]).FirstOrDefault(r=>r.id==junction);if(rule==null)return;Edit("신호 그룹 추가",d=>{var p=d.signals.First(a=>a.junctionId==junction);var g=new RoadMapSignalGroup{name=pedestrian?"추가 보행":"추가 진행",pedestrian=pedestrian};p.groups=p.groups.Concat(new[]{g}).ToArray();p.stages=p.stages.Concat(new[]{new RoadMapStage{name=g.name,yellow=pedestrian?0:3,groups=new[]{g.id}}}).ToArray();AddProgramFacilities(d,new RoadMapSignalProgram{junctionId=junction,groups=new[]{g}},rule);});}
 void CreateProgram(){if(string.IsNullOrWhiteSpace(junction)){if(notify!=null)notify("교차로 ID가 필요합니다.");return;}var rule=(session.Baseline.junctionRules??new HybridJunctionRule[0]).FirstOrDefault(r=>r.id==junction);if(rule==null){if(notify!=null)notify("기준 지도에 존재하는 교차로 ID를 입력하세요.");return;}Edit("기본 신호 생성",d=>{d.signals=d.signals.Where(a=>a.junctionId!=junction).ToArray();d.facilities=d.facilities.Where(f=>f.junctionId!=junction||(f.kind!="vehicleSignal"&&f.kind!="pedestrianSignal")).ToArray();var p=new RoadMapSignalProgram{junctionId=junction};var groups=new System.Collections.Generic.List<RoadMapSignalGroup>();var stages=new System.Collections.Generic.List<RoadMapStage>();for(int axis=0;axis<2;axis++)foreach(int sign in new[]{1,-1}){var ids=new System.Collections.Generic.List<string>();foreach(int t in new[]{-1,0,1}){if(t<0&&!rule.allowLeft||t==0&&!rule.allowStraight||t>0&&!rule.allowRight)continue;var g=new RoadMapSignalGroup{name="차량 "+axis+" / "+sign+" / "+t,axis=axis,sign=sign,turn=t};groups.Add(g);ids.Add(g.id);}if(ids.Count>0)stages.Add(new RoadMapStage{name="분리 진행 "+axis+"/"+sign,groups=ids.ToArray()});}if(rule.crosswalk){var ids=new System.Collections.Generic.List<string>();for(int axis=0;axis<2;axis++)foreach(int sign in new[]{1,-1}){var g=new RoadMapSignalGroup{name="보행 "+axis+"/"+sign,pedestrian=true,axis=axis,sign=sign};groups.Add(g);ids.Add(g.id);}stages.Add(new RoadMapStage{name="보행",green=10,yellow=0,groups=ids.ToArray()});}p.groups=groups.ToArray();p.stages=stages.ToArray();AddProgramFacilities(d,p,rule);d.signals=d.signals.Concat(new[]{p}).ToArray();});}
 void AddProgramFacilities(RoadMapDocument d,RoadMapSignalProgram p,HybridJunctionRule rule){
  var facilities=d.facilities.ToList();var direction=new Vector3(rule.dx,0,rule.dz).normalized;if(direction.sqrMagnitude<.1f)direction=Vector3.forward;float[] half={5,5};foreach(var a in rule.approaches??new HybridApproach[0]){int axis=Mathf.Abs(Vector3.Dot(new Vector3(a.dx,0,a.dz).normalized,direction))>.7f?0:1;half[axis]=Mathf.Max(half[axis],a.width*.5f);}var center=rule.V();
  foreach(var g in p.groups){var dir=(g.axis==0?direction:TrafficSystem.Right(direction))*g.sign;string kind=g.pedestrian?"crosswalk":"stopLine";var mark=facilities.FirstOrDefault(f=>f.junctionId==p.junctionId&&f.kind==kind&&f.axis==g.axis&&f.sign==g.sign);if(mark==null){var at=center-dir*(half[1-g.axis]+(g.pedestrian?TrafficJunction.CrosswalkCentreOffset:4));mark=new RoadMapFacility{id="facility:"+Guid.NewGuid().ToString("N"),kind=kind,junctionId=p.junctionId,axis=g.axis,sign=g.sign,x=Mathf.Clamp(at.x,0,session.Baseline.width),z=Mathf.Clamp(at.z,0,session.Baseline.depth),yaw=Quaternion.LookRotation(dir).eulerAngles.y,width=g.pedestrian?half[g.axis]*2:half[g.axis],length=g.pedestrian?2.4f:.4f};facilities.Add(mark);}var pos=center+dir*(half[1-g.axis]+4)+TrafficSystem.Right(dir)*(half[g.axis]+1+(g.pedestrian?0:g.turn*2.6f));facilities.Add(new RoadMapFacility{id="facility:"+Guid.NewGuid().ToString("N"),kind=g.pedestrian?"pedestrianSignal":"vehicleSignal",junctionId=p.junctionId,axis=g.axis,sign=g.sign,x=Mathf.Clamp(pos.x,0,session.Baseline.width),z=Mathf.Clamp(pos.z,0,session.Baseline.depth),yaw=Quaternion.LookRotation(dir).eulerAngles.y,groupId=g.id,targetId=mark.id,text=g.name,height=g.pedestrian?2.6f:4.5f});if(g.pedestrian)g.crosswalkId=mark.id;}
  d.facilities=facilities.ToArray();
 }
 Vector3 LanePosition(RoadMapLane l,int i){return (dragLane==l.id&&dragPoint==i?dragPosition:l.points[i].V(l.heights!=null&&i<l.heights.Length?l.heights[i]:0))+Vector3.up*.22f;}
 public static bool AllowsFacilityPick(string intent){return string.IsNullOrEmpty(intent)||intent=="target"||intent=="groupWalk";}
 public bool SceneGUI(SceneView view,Event e){if(e==null||e.alt)return false;if(e.type==EventType.KeyDown){if(e.keyCode==KeyCode.F){Focus();e.Use();return true;}if(e.keyCode==KeyCode.Escape){dragFacility="";dragLane="";pending="";e.Use();return true;}if(e.keyCode==KeyCode.W)tool=0;if(e.keyCode==KeyCode.E)tool=1;if(e.keyCode==KeyCode.R)tool=2;}
  if(e.rawType==EventType.MouseUp&&dragLane!=""){string id=dragLane;int n=dragPoint;Vector3 pos=dragPosition;dragLane="";Edit("차로 점 이동",d=>RoadMapAuthoringOperations.MovePoint(d,id,n,pos));}if(e.rawType==EventType.MouseUp&&dragFacility!=""){string id=dragFacility;Vector3 pos=facilityDragPosition;float yaw=facilityDragYaw,scale=facilityDragScale;dragFacility="";Edit("시설 변형",d=>{var f=d.facilities.First(a=>a.id==id);f.x=pos.x;f.z=pos.z;f.yaw=yaw;f.scale=scale;});}float drawRadius=Mathf.Max(100,view.size*2.5f);var old=Handles.color;foreach(var l in D.lanes){Bounds cached;if(l.id!=laneId&&laneBounds.TryGetValue(l.id,out cached)&&cached.SqrDistance(view.pivot)>drawRadius*drawRadius)continue;if(l.disabled||l.points==null||l.points.Length<2)continue;Handles.color=l.id==laneId?Color.yellow:new Color(0,.9f,1,.7f);for(int i=1;i<l.points.Length;i++){var a=LanePosition(l,i-1);var b=LanePosition(l,i);Handles.DrawAAPolyLine(l.id==laneId?4:2,a,b);if(l.id==laneId&&(b-a).sqrMagnitude>.1f){var dir=(b-a).normalized;var mid=(a+b)*.5f;Handles.DrawLine(mid,mid-dir*2+Quaternion.Euler(0,90,0)*dir);Handles.DrawLine(mid,mid-dir*2-Quaternion.Euler(0,90,0)*dir);}}}
  foreach(var f in D.facilities){Handles.color=f.id==facilityId?Color.yellow:Color.magenta;Handles.DrawWireDisc(f.Position+Vector3.up*.3f,Vector3.up,Mathf.Max(.8f,HandleUtility.GetHandleSize(f.Position)*.025f));}
  var lane=Lane;if(lane!=null)for(int i=0;i<lane.points.Length;i++){int n=i;EditorGUI.BeginChangeCheck();Vector3 p=Handles.PositionHandle(dragLane==lane.id&&dragPoint==i?dragPosition:lane.points[i].V(lane.heights!=null&&i<lane.heights.Length?lane.heights[i]:0),Quaternion.identity);if(EditorGUI.EndChangeCheck()){point=n;dragLane=lane.id;dragPoint=n;dragPosition=p;view.Repaint();}}
  var facility=Facility;if(facility!=null){EditorGUI.BeginChangeCheck();var pos=dragFacility==facility.id?facilityDragPosition:facility.Position;float yaw=dragFacility==facility.id?facilityDragYaw:facility.yaw,scale=dragFacility==facility.id?facilityDragScale:facility.scale;if(tool==0)pos=Handles.PositionHandle(pos,Quaternion.identity);else if(tool==1)yaw=Handles.Disc(Quaternion.Euler(0,yaw,0),pos,Vector3.up,HandleUtility.GetHandleSize(pos),false,0).eulerAngles.y;else scale=Handles.ScaleSlider(scale,pos,Vector3.right,Quaternion.identity,HandleUtility.GetHandleSize(pos),.1f);if(EditorGUI.EndChangeCheck()){dragFacility=facility.id;facilityDragPosition=pos;facilityDragYaw=yaw;facilityDragScale=Mathf.Max(.1f,scale);view.Repaint();}}
  Handles.color=old;if(e.type==EventType.Layout&&GUIUtility.hotControl==0)HandleUtility.AddDefaultControl(GUIUtility.GetControlID(FocusType.Passive));if(e.type!=EventType.MouseDown||e.button!=0||GUIUtility.hotControl!=0)return false;Ray ray=HandleUtility.GUIPointToWorldRay(e.mousePosition);float distance;if(!new Plane(Vector3.up,Vector3.zero).Raycast(ray,out distance))return false;Vector3 hit=ray.GetPoint(distance);
  if(pending=="place"){Edit("시설 배치",d=>facilityId=RoadMapAuthoringOperations.CreateFacility(d,kind,type,hit));laneId="";pending="";e.Use();return true;}
  var pickedFacility=AllowsFacilityPick(pending)?D.facilities.OrderBy(f=>(f.Position-hit).sqrMagnitude).FirstOrDefault():null;if(pickedFacility!=null&&Vector3.Distance(pickedFacility.Position,hit)<Mathf.Max(2,HandleUtility.GetHandleSize(hit)*.035f)){if(pending=="groupWalk"){string id=pickedFacility.id;if(pickedFacility.kind!="crosswalk"){if(notify!=null)notify("횡단보도를 선택하세요.");return false;}Edit("보행 그룹 연결",d=>{var p=d.signals.First(a=>a.junctionId==junction);p.groups.First(a=>a.id==selectedGroup).crosswalkId=id;foreach(var f in d.facilities.Where(a=>a.groupId==selectedGroup))f.targetId=id;});pending="";}else if(pending=="target"&&facility!=null){Edit("시설 대상 연결",d=>{var f=d.facilities.First(a=>a.id==facility.id);f.targetId=pickedFacility.id;var program=d.signals.FirstOrDefault(a=>a.junctionId==f.junctionId);if(pickedFacility.kind=="crosswalk"&&program!=null){var group=program.groups.FirstOrDefault(a=>a.id==f.groupId&&a.pedestrian);if(group!=null)group.crosswalkId=pickedFacility.id;}});pending="";}else SelectFacility(pickedFacility.id);e.Use();return true;}
  RoadMapLane picked=null;float best=float.MaxValue;foreach(var l in D.lanes.Where(l=>!l.disabled&&l.points!=null))for(int i=1;i<l.points.Length;i++){var a=l.points[i-1].V();var b=l.points[i].V();var v=b-a;var p=a+v*Mathf.Clamp01(Vector3.Dot(hit-a,v)/Mathf.Max(.0001f,v.sqrMagnitude));float dist=Vector3.Distance(hit,p);if(dist<=Mathf.Max(1,l.width)&&dist<best){best=dist;picked=l;}}
  if(picked==null)return false;if(pending=="groupLane"){string id=picked.id;Edit("신호 차로 연결",d=>{var g=d.signals.First(a=>a.junctionId==junction).groups.First(a=>a.id==selectedGroup);g.laneIds=g.laneIds.Concat(new[]{id}).Distinct().ToArray();});pending="";}else if(pending=="connect"&&lane!=null){string target=picked.id;Edit("차로 연결",d=>RoadMapAuthoringOperations.Connect(d,lane.id,target,turn-2,change-1));pending="";}else if(pending=="bind"&&facility!=null){string target=picked.id;Edit("시설 차로 연결",d=>{var f=d.facilities.First(a=>a.id==facility.id);f.laneId=target;f.junctionId=d.lanes.First(a=>a.id==target).ruleId;});pending="";}else SelectLane(picked.id);e.Use();return true;
 }
